import{b as e,O as s,g as t,j as o}from"./chunks/framework.DcaUmd3X.js";const b=JSON.parse('{"title":"Mac 下 WebStorm 插件及配置","description":"","frontmatter":{"tags":["工具","插件"]},"headers":[],"relativePath":"blog/tools/mac-webstorm-setup/index.md","filePath":"个人博客/工具篇/7.mac下webstorm插件及配置.md","lastUpdated":1781623812000}'),n={name:"blog/tools/mac-webstorm-setup/index.md"};function r(i,a,p,l,c,h){return s(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="mac-下-webstorm-插件及配置" tabindex="-1">Mac 下 WebStorm 插件及配置 <a class="header-anchor" href="#mac-下-webstorm-插件及配置" aria-label="Permalink to &quot;Mac 下 WebStorm 插件及配置&quot;">​</a></h1><h2 id="安装卸载" tabindex="-1">安装卸载 <a class="header-anchor" href="#安装卸载" aria-label="Permalink to &quot;安装卸载&quot;">​</a></h2><blockquote><p>网上关于卸载 WebStorm 的说法参差不齐，总结了一下</p></blockquote><p>官网安装：<a href="https://www.jetbrains.com/webstorm/" target="_blank" rel="noreferrer">传送门</a></p><p>Mac 下重置 WebStorm，需要删除四个部分的文件，使用终端操作：</p><p><strong>Preferences</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 切换 Preferences 文件夹</span></span>
<span class="line"><span>cd ~/Library/Preferences/</span></span>
<span class="line"><span># 删除 WebStorm 配置文件</span></span>
<span class="line"><span>rm -f com.jetbrains.WebStorm.plist</span></span></code></pre></div><p><strong>Caches</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 切换 Caches</span></span>
<span class="line"><span>cd ~/Library/Caches/</span></span>
<span class="line"><span># 删除 WebStorm 缓存（注意：只删 WebStorm 的，别把其他 JetBrains 产品删了）</span></span>
<span class="line"><span>rm -rf WebStorm*</span></span></code></pre></div><p><strong>Plugins</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 切换 Application Support 文件夹</span></span>
<span class="line"><span>cd ~/Library/Application\\ Support</span></span>
<span class="line"><span># 删除 WebStorm 插件和数据</span></span>
<span class="line"><span>rm -rf WebStorm*</span></span></code></pre></div><p><strong>Logs</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 进入 Logs 文件夹</span></span>
<span class="line"><span>cd ~/Library/Logs/</span></span>
<span class="line"><span># 删除 WebStorm 日志</span></span>
<span class="line"><span>rm -rf WebStorm*</span></span></code></pre></div><blockquote><p>⚠️ 注意：上面用 <code>WebStorm*</code> 匹配只删 WebStorm 相关文件，不要直接用 <code>rm -rf JetBrains</code>，否则会把 IntelliJ、PyCharm 等其他 JetBrains 产品的配置也一并删掉。</p></blockquote><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h2><p>以下插件不分先后顺序，用到了绝对让你工作事半功倍。</p><h3 id="one-dark-theme" tabindex="-1">One Dark Theme <a class="header-anchor" href="#one-dark-theme" aria-label="Permalink to &quot;One Dark Theme&quot;">​</a></h3><p>尝试了很多主题，确实发现 WebStorm 相较于 VS Code 的渲染高亮确实差点意思，这个主题使用起来算是还不错的。</p><h3 id="atom-material-icons" tabindex="-1">Atom Material Icons <a class="header-anchor" href="#atom-material-icons" aria-label="Permalink to &quot;Atom Material Icons&quot;">​</a></h3><p>侧边栏文件图标渲染显示，不同类型的文件有对应的 icon，找文件一眼就能定位。</p><h3 id="codeglance" tabindex="-1">CodeGlance <a class="header-anchor" href="#codeglance" aria-label="Permalink to &quot;CodeGlance&quot;">​</a></h3><p>Sublime 和 VS Code 都默认会在编辑器右侧显示代码缩略图，WebStorm 需要自己装插件实现。</p><h3 id="gittoolbox" tabindex="-1">GitToolBox <a class="header-anchor" href="#gittoolbox" aria-label="Permalink to &quot;GitToolBox&quot;">​</a></h3><p>代码行尾显示 Git 提交信息和作者，不用每次 blame 就能看到谁改的。</p><h3 id="wechat-mini-program-support" tabindex="-1">Wechat Mini Program Support <a class="header-anchor" href="#wechat-mini-program-support" aria-label="Permalink to &quot;Wechat Mini Program Support&quot;">​</a></h3><p>小程序开发者的福音，支持微信小程序文件格式（<code>.wxml</code>、<code>.wxss</code>、<code>.wxs</code> 等）的语法高亮和代码提示。</p><h3 id="env-files-support" tabindex="-1">.env Files Support <a class="header-anchor" href="#env-files-support" aria-label="Permalink to &quot;.env Files Support&quot;">​</a></h3><p>环境变量文件类型支持，让 <code>.env</code> 文件有语法高亮和自动补全。</p><h3 id="translation" tabindex="-1">Translation <a class="header-anchor" href="#translation" aria-label="Permalink to &quot;Translation&quot;">​</a></h3><p>翻译插件，内置 Google / 百度 / 有道三大翻译引擎，可以划词翻译代码中的变量名，很适合英文不太好的同学。</p><h3 id="ignore" tabindex="-1">.ignore <a class="header-anchor" href="#ignore" aria-label="Permalink to &quot;.ignore&quot;">​</a></h3><p>使用 Git 的时候经常需要忽略一些不想提交的文件，这个插件提供 <code>.gitignore</code> 语法高亮和模板生成。</p><p><code>.gitignore</code> 不需要完全从头自己写，GitHub 提供了一系列配置模板：<a href="https://github.com/github/gitignore" target="_blank" rel="noreferrer">https://github.com/github/gitignore</a></p><h3 id="js-graphql" tabindex="-1">JS GraphQL <a class="header-anchor" href="#js-graphql" aria-label="Permalink to &quot;JS GraphQL&quot;">​</a></h3><p>如果你用 GraphQL 的话必装，提供 <code>.graphql</code> 文件的语法高亮、config 支持等。</p><p>📢：插件后续会持续更新，有小伙伴觉得有漏掉的欢迎留言补充~</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><h3 id="键盘映射" tabindex="-1">键盘映射 <a class="header-anchor" href="#键盘映射" aria-label="Permalink to &quot;键盘映射&quot;">​</a></h3><p>这里我选择的是 VS Code (mac) 键位，可以按照自己习惯选择。</p><h3 id="启动时不打开上次项目" tabindex="-1">启动时不打开上次项目 <a class="header-anchor" href="#启动时不打开上次项目" aria-label="Permalink to &quot;启动时不打开上次项目&quot;">​</a></h3><p>设置 → Appearance &amp; Behavior → System Settings → 将 Project 下 <code>Reopen projects on startup</code> 选项取消。</p><h3 id="取消代码中的黄色警告线" tabindex="-1">取消代码中的黄色警告线 <a class="header-anchor" href="#取消代码中的黄色警告线" aria-label="Permalink to &quot;取消代码中的黄色警告线&quot;">​</a></h3><p>设置 → Editor → Color Scheme → General → 找到 <code>Weak Warning</code>，取消选中的颜色提示。</p>`,43)])])}const m=e(n,[["render",r]]);export{b as __pageData,m as default};
